import { defineScript, gui, msg, hash, vmath, window, go, print } from '../../../engine';
import { t, cat, S } from '../../../lua';
import { G } from '../../globals';
import gooey from '../../gooey/gooey';
import inspect from '../../inspect';
import defsave from '../../defsave/defsave';
import loc from '../../shared/locsheets';

void inspect;

defineScript('/main/timewarp/timewarp.gui_script', () => {
  const productName = "OoR"; void productName;
  const currentPage = "rankUp_popup";
  const controller = "main:/menu#controller";
  let enabled: any = false;
  let pause = true;
  let amount: any = 0;
  let spring: any = 1;
  let base: any = 0;
  let tock: any = undefined;

  const color: Record<string, string> = {
    Common: "fancybutton_darkgrey",
    Wild: "fancybutton_brown",
    Rare: "fancybutton_green",
    Epic: "fancybutton_blue",
    Legendary: "fancybutton_purple",
    Exotic: "fancybutton_orange",
  }; void color;

  /* ******************************************
              SCREEN FIT
  ******************************************** */

  /* The scene is drawn for a 750x1334 phone and Defold fits that rectangle
  into the window, so on any other shape the room left over turns into margin
  and anything full bleed stops reaching the edges. The root goes on a plain
  uniform fit, and the parts that have to touch an edge are placed against the
  real one. The long version of this note is in main/nav/header.gui_script. */
  const DESIGN_W = 750;
  const DESIGN_H = 1334;
  const HEADER_DEPTH = 255.5; // underside of the header's top bar, from the top edge
  const FOOTER_TOP = 105; // top of the header's bottom bar, from the bottom edge

  const screen = { w: 0, h: 0 };

  // The screen in design units, or nil if it has not changed since last call.
  function screen_changed(): [number, number] | undefined {
    const [ww, wh] = window.get_size();
    const scale = Math.min(ww / DESIGN_W, wh / DESIGN_H);
    const w = ww / scale, h = wh / scale;
    if (Math.abs(w - screen.w) < 1 && Math.abs(h - screen.h) < 1) return undefined;
    screen.w = w; screen.h = h;
    const root = gui.get_node("root");
    gui.set_adjust_mode(root, gui.ADJUST_FIT);
    gui.set_xanchor(root, gui.ANCHOR_NONE);
    gui.set_yanchor(root, gui.ANCHOR_NONE);
    return [w, h];
  }

  function screen_left() { return (DESIGN_W - screen.w) / 2; } void screen_left;
  function screen_bottom() { return (DESIGN_H - screen.h) / 2; }
  function screen_top() { return screen_bottom() + screen.h; }
  function content_top() { return screen_top() - HEADER_DEPTH; } void content_top;
  function content_bottom() { return screen_bottom() + FOOTER_TOP; } void content_bottom;

  function place(id: string, x?: number, y?: number) {
    const node = gui.get_node(id);
    const p = gui.get_position(node);
    gui.set_position(node, vmath.vector3(t(x) ? x : p.x, t(y) ? y : p.y, p.z));
    return node;
  }

  function resize(id: string, w?: number, h?: number) {
    const node = gui.get_node(id);
    const s = gui.get_size(node);
    gui.set_size(node, vmath.vector3(t(w) ? w : s.x, t(h) ? h : s.y, s.z));
    return node;
  } void resize;

  function layout_screen() {
    const r = screen_changed();
    if (!r) return;
    const [, h] = r;
    place("root/center", undefined, screen_bottom() + h / 2);
  }

  function unpause() {
    pause = false;
  }

  function animate_card() {
    const node = gui.get_node("upgradecard/bg");
    gui.set_scale(node, vmath.vector3(0.9, 0.9, 0.9));
    gui.animate(node, gui.PROP_SCALE, vmath.vector3(1, 1, 1), go.EASING_OUTELASTIC, 0.75, 0, unpause);
  }

  /* Tock, the patron for time (gdd/heroes-roster.md), winds its key and the
  warp stretches: the card shows the warp bought, then the warp Tock made of
  it. */
  function show_tock() {
    if (!t(tock)) {
      tock = gui.new_box_node(vmath.vector3(0, 0, 0), vmath.vector3(200, 200, 0));
      gui.set_texture(tock, "main");
      gui.play_flipbook(tock, "patron_tock");
      gui.set_parent(tock, gui.get_node("upgradecard/bg"));
    }
    const card = gui.get_size(gui.get_node("upgradecard/bg"));
    gui.set_enabled(tock, true);
    gui.set_position(tock, vmath.vector3(card.x / 2 + 140, card.y * 0.3, 0));
    gui.animate(tock, "position.x", card.x / 2 - 30, gui.EASING_OUTBACK, 0.4, 0.6, function () {
      gui.animate(tock, "rotation.z", -12, gui.EASING_INOUTSINE, 0.15, 0, undefined, gui.PLAYBACK_ONCE_PINGPONG);
      const name = gui.get_node("card/name");
      gui.set_text(name, cat(S.upper(loc.get("TIMEWARP_NAME", Math.floor(amount * 10 + 0.5) / 10)), "\n", loc.get("HERO_BONUS_WOUNDSPRING", [cat(Math.floor((spring - 1) * 100 + 0.5), "%")])));
      gui.animate(name, "scale", vmath.mul(gui.get_scale(name), 1.15), gui.EASING_OUTQUAD, 0.12, 0, undefined, gui.PLAYBACK_ONCE_PINGPONG);
    });
  }

  function update_card(_card?: any) {
    gui.set_text(gui.get_node("card/name"), S.upper(loc.get("TIMEWARP_NAME", spring > 1 && t(base) ? base : amount)));
    if (spring > 1) show_tock(); else if (t(tock)) gui.set_enabled(tock, false);
    let descText = "TIMEWARP_DESC";
    if (amount > 1) descText = cat(descText, "_PLURAL");
    gui.set_text(gui.get_node("card/text"), loc.get(descText, amount));
    animate_card();
  }

  function refresh_all() {
    if (t(enabled)) {
      // `card` is an unset global in this script.
      update_card(G.card);
    }
  }

  return {
    init(_self) {
      layout_screen();
      print(S.upper(currentPage), "init", enabled);
      gui.set_enabled(gui.get_node("root"), enabled);
      gui.set_render_order(15);
      gooey.acquire_input();
      const nameNode = gui.get_node("card/name"); void nameNode;
      const descNode = gui.get_node("card/text"); void descNode;
    },

    on_input(_self, action_id, action) {
      if (action_id !== undefined && action_id !== null && t(enabled)) {
        if (action_id === hash("touch") && action.pressed && !pause) {
          msg.post(controller, "show_dungeonmine");
        }
      }
    },

    on_message(_self, message_id, message, _sender) {
      if (message_id === hash("set_enabled")) {
        enabled = message.enabled;
        print(S.upper(currentPage), "enabled", enabled);
        gui.set_enabled(gui.get_node("root"), enabled);
        msg.post("main:/background#background", "set_enabled", { enabled: enabled, effect: { type: "tunnel", texture: "backgrounds", flipbook: "warp" } });
        if (t(enabled)) {
          pause = true;
          amount = t(message.amount) ? message.amount : undefined;
          spring = t(message.spring) ? message.spring : 1;
          base = t(message.base) ? message.base : amount;
          refresh_all();
        }
      } else if (message_id === hash("refresh_all")) {
        // `card` is a global here; indexing it while nil raises, as in the Lua.
        if (!t(G.card.message) && t(G.card.type) && t(G.card.id)) {
          G.card = defsave.get(G.card.type, G.card.id);
        }
        refresh_all();
      }
    },

    update(_self, _dt) {
      layout_screen();
    },
  };
});
